  page: Type.Optional(Type.Integer({ minimum: 1 })),
  evidence: Type.Optional(Type.String({ minLength: 1, maxLength: 500 })),
});

const ExamOptionSchema = Type.Object({
  value: Type.String(),
  label: Type.String(),
